import zipfile
import xml.etree.ElementTree as ET
import re

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}
M = NS['m']

def col_letter(ref):
    return re.match(r'[A-Z]+', ref).group(0)

def col_to_num(letters):
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - ord('A') + 1)
    return n - 1  # 0-based

path = 'budget.xlsx'
z = zipfile.ZipFile(path)
print('Files in archive:')
for name in z.namelist():
    print(' ', name)

wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rel_map = {}
for rel in rels:
    rel_map[rel.get('Id')] = rel.get('Target')

shared = {}
try:
    ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for i, si in enumerate(ss.findall(f'{{{M}}}si')):
        text = ''.join(t.text or '' for t in si.iter(f'{{{M}}}t'))
        shared[i] = text
except KeyError:
    pass

sheets = []
for sh in wb.find(f'{{{M}}}sheets'):
    sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))

for name, rid in sheets:
    target = rel_map[rid]
    if not target.startswith('xl/'):
        target = 'xl/' + target.lstrip('/')
    print(f'\n===== Sheet: {name} ({target}) =====')
    root = ET.fromstring(z.read(target))
    for row in root.iter(f'{{{M}}}row'):
        cells = []
        for c in row.findall(f'{{{M}}}c'):
            ref = c.get('r')
            t = c.get('t')
            v = c.find(f'{{{M}}}v')
            val = v.text if v is not None else None
            if t == 's' and val is not None:
                val = shared[int(val)]
            elif t == 'inlineStr':
                is_el = c.find(f'{{{M}}}is')
                if is_el is not None:
                    val = ''.join(x.text or '' for x in is_el.iter(f'{{{M}}}t'))
            cells.append(f'{ref}={val!r}')
        if cells:
            print('row', row.get('r'), '|', ' '.join(cells))

